const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const agudo = ee.Geometry.Point([-53.2500, -29.6447]);
  const studyArea = agudo.buffer(5000); // 5km buffer

  // Date ranges (3-day windows around target dates)
  const date1_start = '2023-11-04';
  const date1_end = '2023-11-06';
  const date2_start = '2023-11-20';
  const date2_end = '2023-11-22';

  // 2. Data Acquisition
  function getSentinel2Collection(startDate, endDate) {
    return ee.ImageCollection('COPERNICUS/S2_HARMONIZED')
      .filterBounds(studyArea)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80));
  }

  const col1 = getSentinel2Collection(date1_start, date1_end);
  const col2 = getSentinel2Collection(date2_start, date2_end);

  const col1_size = col1.size().getInfo();
  const col2_size = col2.size().getInfo();

  console.log(`Nov 5 window Images: ${col1_size}`);
  console.log(`Nov 21 window Images: ${col2_size}`);

  // Check for empty collections
  if (col1_size === 0 || col2_size === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Create composites and calculate water area
  function calculateWaterArea(imageCollection) {
    // Create median composite
    const composite = imageCollection.median();

    // Calculate MNDWI for water detection (Green - SWIR) / (Green + SWIR)
    const mndwi = composite.normalizedDifference(['B3', 'B11']);

    // Create water mask (MNDWI > 0 typically indicates water)
    const waterMask = mndwi.gt(0);

    // Calculate water area in square meters
    const waterArea = waterMask.multiply(ee.Image.pixelArea())
      .reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: studyArea,
        scale: 100,
        maxPixels: 1e9
      }).get('nd');

    return waterArea;
  }

  const area1 = calculateWaterArea(col1);
  const area2 = calculateWaterArea(col2);

  // Get the actual values
  const area1_val = area1.getInfo();
  const area2_val = area2.getInfo();

  console.log(`Nov 5 water area: ${area1_val ? (area1_val / 1000000).toFixed(2) : 'None'} km²`);
  console.log(`Nov 21 water area: ${area2_val ? (area2_val / 1000000).toFixed(2) : 'None'} km²`);

  // 4. Validation & Final Answer
  if (area1_val === null || area2_val === null || 
      isNaN(area1_val) || isNaN(area2_val)) {
    console.log("<answer>C3</answer>");
  } else if (area1_val === 0 || area2_val === 0) {
    console.log("<answer>C2</answer>");
  } else if (area2_val > area1_val) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
